NAME = 'CzeCSP: Czech Český studijní překlad'
BOOK = 'Colossians'

CHAPTERS = {
    1: {
        1: 'Pavel, z Boží vůle apoštol Krista Ježíše, a bratr Timoteus',
        2: 'svatým a věrným bratřím v Kristu v Kolosách: Milost vám a pokoj od Boha Otce našeho [a Pána Ježíše Krista].',
        3: '⌈Vždy, když se⌉ za vás modlíme, děkujeme Bohu [a] Otci našeho Pána Ježíše Krista --',
        4: 'neboť jsme slyšeli o vaší víře v Kristu Ježíši a o lásce, kterou máte ke všem svatým --',
        5: 'pro naději, která je pro vás uložena v nebesích. O ní jste slyšeli již dříve ve slovu pravdy -- evangeliu,',
        6: 'jež k vám přišlo. A jako na celém světě přináší ovoce a roste, tak je tomu i mezi vámi od toho dne, kdy jste je uslyšeli a poznali Boží milost v pravdě',
        7: 'tak, jak jste se naučili od Epafry, našeho milovaného spoluotroka, jenž je věrný služebník Kristův pro vás.',
        8: 'On nám také pověděl o vaší lásce v Duchu.',
        9: 'Proto i my, od toho dne, kdy jsme to uslyšeli, nepřestáváme se za vás modlit a vyprošovat, abyste byli naplněni poznáním jeho vůle ve veškeré moudrosti a duchovním pochopení,',
        10: 'abyste vedli život hodný Pána ⌈a ve všem se mu líbili⌉, abyste nesli ovoce v ⌈každém dobrém skutku⌉ a rostli v poznání Boha',
        11: 'a abyste byli posilováni každou mocí podle síly jeho slávy k veškeré vytrvalosti a trpělivosti⌈, s radostí',
        12: 'vzdávajíce⌉ díky [Bohu] [a] Otci, který nás učinil způsobilými k účasti na podílu svatých ve světle.',
        13: 'On nás vysvobodil z pravomoci temnoty a přenesl do království ⌈Syna své lásky⌉,',
        14: 'v němž máme [skrze jeho krev] vykoupení, odpuštění hříchů.',
        15: 'On je obraz neviditelného Boha, prvorozený ⌈všeho stvoření⌉,',
        16: 'neboť v něm bylo stvořeno všechno na nebesích i na zemi, věci viditelné i neviditelné, ať trůny nebo panstva, vlády nebo autority; všechno je stvořeno skrze něho a pro něho.',
        17: 'On je přede vším a všechno v něm spočívá.',
        18: 'A on je hlavou těla, církve. On je počátek, prvorozený z mrtvých, aby on sám ⌈zaujal ve všem první místo⌉,',
        19: 'neboť se Otci zalíbilo, aby v něm přebývala veškerá plnost',
        20: 'a aby skrze něho smířil všechno se sebou a způsobil pokoj skrze krev jeho kříže -- aby [skrze něho] smířil vše jak na zemi, tak v nebesích.',
        21: 'I vás, kteří jste kdysi byli odcizeni a myslí nepřátelští ve zlých skutcích,',
        22: 'nyní smířil ⌈ve svém lidském těle⌉ skrze [svou] smrt, aby vás před sebou postavil svaté, bez poskvrny a bez úhony,',
        23: 'zůstáváte–li vskutku na víře založeni a v ní pevni a nevzdálíte–li se od naděje evangelia, které jste slyšeli, které bylo hlásáno v celém stvoření pod nebem a kterého jsem se já, Pavel, stal služebníkem.',
        24: 'Nyní se raduji v utrpeních pro vás a ve svém těle doplňuji, co zbývá ze soužení Kristových pro jeho tělo, jímž jest církev.',
        25: 'Jejím služebníkem jsem se stal podle Boží správy, která mi pro vás byla svěřena, abych naplnil slovo Boží --',
        26: 'to tajemství, které bylo od věků a od prvních pokolení ukryté, nyní však bylo zjeveno jeho svatým,',
        27: 'kterým Bůh toužil oznámit, jaké je bohatství slávy tohoto tajemství mezi pohany: tím tajemstvím je Kristus ve vás, naděje slávy.',
        28: 'Jeho my zvěstujeme napomínajíce každého člověka a vyučujíce každého člověka ve vší moudrosti, abychom každého postavili dokonalého v Kristu.',
        29: 'Proto také usilovně pracuji a zápasím ⌈v souladu s⌉ jeho působením, které ⌈je ve mně mocné⌉.',
    },
    2: {
        1: 'Chci, abyste věděli, jaký zápas vedu pro vás a pro ty, kdo jsou v Laodiceji, i pro všechny, kteří ⌈mne ani osobně⌉ neviděli.',
        2: 'Zápasím o to, aby byli povzbuzeni ve svém srdci a navzájem spojeni v lásce byli dovedeni do celého bohatství plné jistoty porozumění, k plnému poznání ⌈Božího tajemství, Krista⌉,',
        3: 've kterém jsou skryty všechny poklady moudrosti a poznání.',
        4: 'Toto říkám proto, aby vás nikdo nemátl zdánlivě přesvědčivými řečmi.',
        5: 'Neboť i když jsem tělem nepřítomen, přece jsem duchem s vámi a s radostí vidím váš řád a pevnost vaší víry v Krista.',
        6: 'Když jste tedy přijali Krista Ježíše, Pána, pak v něm žijte,',
        7: 'zakořeněni a budováni v něm, upevňujte se ve víře, jak jste byli vyučeni, rozhojňujíce se ⌈v ní s děkováním⌉.',
        8: 'Dávejte si pozor, ať vás někdo neodvede jako zajatce skrze filozofii-- prázdný svod podle lidské tradice, podle živlů světa, a ne podle Krista.',
        9: 'Neboť v něm tělesně přebývá veškerá plnost Božství.',
        10: 'I vy jste v něm naplněni. On je hlavou každé vlády a moci.',
        11: 'V něm jste byli také obřezáni obřízkou, která nebyla udělána lidskou rukou, nýbrž spočívala ve svlečení těla hříchů, v obřízce Kristově,',
        12: 'když jste byli spolu s ním ve křtu pohřbeni a v něm jste byli spolu i vzkříšeni skrze víru ⌈ v působení Boha⌉, který ho vzkřísil z mrtvých.',
        13: 'I vás, když jste byli mrtvi v proviněních a neobřízce svého těla, spolu s ním obživil, když nám všechna provinění odpustil',
        14: 'a vymazal ⌈rukou psaný záznam⌉, který svými ustanoveními svědčil proti nám a který nám byl nepřátelský; odstranil jej z našeho středu tím, že jej přibil na kříž.',
        15: 'Tak odzbrojil vlády a autority a veřejně je vystavil na odiv, když je vedl triumfálním průvodem ⌈v něm⌉.',
        16: 'Ať vás tedy nikdo nesoudí pro pokrm a pro nápoj nebo kvůli svátku, novoluní nebo sobotám.',
        17: 'To všechno je stín budoucích věcí, ale ⌈skutečnost je Kristus⌉.',
        18: 'Ať vás nepřipraví o vítěznou cenu nikdo, kdo si libuje v poníženosti a uctívání andělů, ⌈kdo se nechá unášet tím⌉, co viděl, bezdůvodně se nadýmá pod vlivem svého tělesného smýšlení',
        19: 'a nedrží se hlavy, z níž celé tělo, podporováno a drženo pohromadě klouby a spoji, roste Božím růstem.',
        20: 'Jestliže jste s Kristem zemřeli živlům světa, proč si dáváte předpisovat, jako byste žili ve světě:',
        21: 'toho se nedotýkej, to neochutnávej, na to ani nesáhni?',
        22: 'To ⌈se týká⌉ vesměs věcí, které jsou spotřebováním určeny k zániku -- ⌈jsou to lidské příkazy a nauky⌉.',
        23: 'Ty sice ⌈působí zdáním⌉ moudrosti v ochotném uctívání, v pokoře a tvrdé kázni těla, ale nemají žádnou cenu⌈, leč pro uspokojení⌉ těla.',
    },
    3: {
        1: 'Jestliže jste tedy s Kristem vstali, usilujte o to, co je nahoře, kde Kristus sedí na Boží pravici.',
        2: 'Myslete na to, co je nahoře, ne na to, co je na zemi.',
        3: 'Neboť jste zemřeli a váš život je ukryt s Kristem v Bohu.',
        4: 'A když se ukáže Kristus, váš život, tehdy i vy se s ním ukážete ve slávě.',
        5: 'Umrtvěte tedy [své] údy, které jsou na zemi: smilstvo, nečistotu, vášeň, zlou žádost a lakomství, které je modloslužbou.',
        6: '⌈Pro tyto věci⌉ přichází Boží hněv [na ⌈syny neposlušnosti⌉].',
        7: 'I vy jste ⌈tak kdysi jednali⌉, když jste v nich žili.',
        8: 'Ale nyní odložte to všechno: hněv, vztek, špatnost, rouhání a nemístné řeči ze svých úst.',
        9: 'Nelžete jedni druhým, když jste svlékli toho starého člověka s jeho skutky',
        10: 'a oblékli toho nového, který se obnovuje ⌈k pravému poznání podle obrazu⌉ toho, který ho stvořil.',
        11: 'Potom tu už není Řek a Žid, obřízka a neobřízka, barbar, Skytha, otrok a svobodný, ale všechno a ve všem Kristus.',
        12: 'Oblečte se tedy jako vyvolení Boží, svatí a milovaní, v ⌈slitovný soucit,⌉ dobrotu, pokoru, vlídnost a trpělivost.',
        13: 'Snášejte se navzájem a odpouštějte si, má–li kdo něco proti druhému. Jako Pán odpustil vám, odpusťte i vy.',
        14: 'A nad to všechno mějte lásku, která je poutem dokonalosti.',
        15: 'Pokoj Kristův ať rozhoduje ve vašich srdcích; k němu jste byli také povoláni v jednom těle. A buďte vděčni.',
        16: 'Slovo Kristovo ať ve vás bohatě přebývá. Ve vší moudrosti se navzájem vyučujte a napomínejte a ⌈s vděčností⌉ zpívejte Bohu ⌈ve svých srdcích⌉ chvalozpěvy, oslavné zpěvy a duchovní písně.',
        17: 'A všechno, cokoli činíte slovem nebo skutkem, čiňte ve jménu Pána Ježíše a skrze něho děkujte Bohu [a] Otci.',
        18: 'Ženy, podřizujte se svým mužům, jak se sluší v Pánu.',
        19: 'Muži, milujte své ženy a ⌈nebuďte k nim příkří⌉.',
        20: 'Děti, poslouchejte své rodiče ve všem, neboť to je milé ⌈v Pánu⌉.',
        21: 'Otcové, nedrážděte své děti, aby nemalomyslněly.',
        22: 'Otroci, poslouchejte ve všem pozemské pány, ne jen naoko, jako ti, kdo se chtějí zalíbit lidem, ale v upřímnosti srdce, bojíce se Pána.',
        23: 'Cokoli děláte, dělejte z duše jako Pánu, a ne lidem.',
        24: 'Vždyť víte, že od Pána dostanete za odměnu dědictví. Pánu Kristu služte!',
        25: 'Neboť kdo ⌈činí zlé⌉, dostane zpět to, co zlého učinil. ⌈ Bůh nikomu nestraní⌉.',
    },
    4: {
        1: 'Páni, prokazujte otrokům, co je spravedlivé a správné; vždyť víte, že i vy máte Pána v nebi.',
        2: 'V modlitbě buďte vytrvalí; buďte v ní bdělí ⌈a vděční⌉.',
        3: 'Modlete se současně i za nás, aby nám Bůh otevřel dveře slova, abychom mohli mluvit o tajemství Kristovu, pro něž jsem také spoután,',
        4: 'abych je učinil zjevným tak, jak jsem povinen o něm mluvit.',
        5: 'Žijte moudře před těmi, kteří jsou vně, vykupujíce čas.',
        6: 'Vaše řeč ať je vždy laskavá, okořeněná solí, abyste věděli, jak máte každému odpovědět.',
        7: 'Co je se mnou, vám oznámí Tychikos, milovaný bratr, věrný služebník a spoluotrok v Pánu,',
        8: 'jehož jsem k vám poslal právě proto, ⌈abyste se o nás dověděli⌉ a aby povzbudil vaše srdce.',
        9: 'Posílám ho s Onezimem, věrným a milovaným bratrem, jenž je od vás. Ti vám oznámí všechno, co se zde děje.',
        10: 'Pozdravuje vás můj spoluvězeň Aristarchos a Barnabášův bratranec Marek, o němž jste dostali pokyny; až k vám přijde, přijměte ho.',
        11: 'Dále Ježíš zvaný Justus. Oni jsou ze Židů moji jediní spolupracovníci pro Boží království; stali se mou útěchou.',
        12: 'Pozdravuje vás Epafras, který je od vás, otrok Krista [Ježíše]; on za vás ustavičně zápasí na modlitbách, abyste byli postaveni zralí a úplní v celé vůli Boží.',
        13: 'Dosvědčuji mu, že pro vás a pro ty, kdo jsou v Laodiceji a v Hierapoli, vynakládá mnoho namáhavé práce.',
        14: 'Pozdravuje vás milovaný lékař Lukáš a Démas.',
        15: 'Pozdravte bratry v Laodiceji i Nymfu a církev, která je v jeho domě.',
        16: 'A až bude u vás ten to dopis přečten, zařiďte, aby byl přečten také v laodicejském sboru a abyste i vy přečetli ⌈ dopis Laodicejským⌉.',
        17: 'A Archippoviřekněte: Hleď si služby, kterou jsi v Pánu přijal, abys ji plnil.',
        18: 'Pozdrav mou, Pavlovou rukou. Pamatujte na ⌈má pouta⌉. Milost s vámi. [Amen.]',
    },
}
